        test.assert(equip.getSlot(EquipmentSlot.Head)?.typeId === "minecraft:iron_helmet", "Should have iron helmet equipped");
        test.assert(equip.getSlot(EquipmentSlot.Chest)?.typeId === "minecraft:iron_chestplate", "Should have iron chestplate equipped");
        test.assert(equip.getSlot(EquipmentSlot.Legs)?.typeId === "minecraft:iron_leggings", "Should have iron leggings equipped");
        test.assert(equip.getSlot(EquipmentSlot.Feet)?.typeId === "minecraft:iron_boots", "Should have iron boots equipped");
        await test.idle(1 * TicksPerSecond);
        // Give diamond armor
        inv.giveItem(new ItemStack("minecraft:diamond_helmet"));
