        test.assert(equip.getSlot(EquipmentSlot.Head)?.typeId === "minecraft:diamond_helmet", "Should have diamond helmet equipped");
        test.assert(equip.getSlot(EquipmentSlot.Chest)?.typeId === "minecraft:diamond_chestplate", "Should have diamond chestplate equipped");
        test.assert(equip.getSlot(EquipmentSlot.Legs)?.typeId === "minecraft:diamond_leggings", "Should have diamond leggings equipped");
        test.assert(equip.getSlot(EquipmentSlot.Feet)?.typeId === "minecraft:diamond_boots", "Should have diamond boots equipped");
        await test.idle(1 * TicksPerSecond);
        // Remove diamond chestplate from inventory
        inv.removeItem(new ItemStack("minecraft:diamond_chestplate"));
        await test.idle(1 * TicksPerSecond);
        // Assert diamond chestplate is no longer equipped
        test.assert(equip.getSlot(EquipmentSlot.Chest)?.typeId === "minecraft:iron_chestplate", "Iron chestplate should be equipped after removing diamond");
        test.succeed();
